--- from: Assets/BundleResources/Prefabs/Action/ActionPrimaryMapDialog.prefab
---@class UIActionPrimaryMapNode
---@field Env                           	UIActionPrimaryMapNode                  
---@field controller                    	Engine.Modules.LuaBehaviour             
